-- Schema of the synthetic demo database (generated by python -m smartmask.seed)
CREATE TABLE customers (customer_id INTEGER, full_name TEXT, email TEXT, phone TEXT, date_of_birth TEXT, ssn TEXT, aadhaar_no TEXT, pan_no TEXT, city TEXT, kyc_status TEXT, support_note TEXT);
CREATE TABLE accounts (account_id INTEGER, customer_id INTEGER, account_number TEXT, account_type TEXT, balance REAL, opened_on TEXT);
CREATE TABLE cards (card_id INTEGER, customer_id INTEGER, card_number TEXT, card_type TEXT, expiry TEXT, credit_limit REAL);
CREATE TABLE transactions (txn_id INTEGER, account_id INTEGER, reference_no TEXT, amount REAL, merchant TEXT, txn_date TEXT);
